let lastButtonInstance = null;

export default class Button {
    constructor(options) {
        this.options = options;
        lastButtonInstance = this;
    }
}

export function _reset() {
    lastButtonInstance = null;
}

export function _simulatePush(type) {
    if (lastButtonInstance && lastButtonInstance.options.onPush) {
        lastButtonInstance.options.onPush(true, type);
        lastButtonInstance.options.onPush(false, type);
    }
}
